const maps = [["Justitian — plan dzielnicy Dostawców","dzielnica",2400,1600,0],["Targ i studnia przy Bramie","targ-studnia",2100,1400,1],["Lazaret Spitalian","lazaret",1960,1260,1],["Pod Złamanym Skrzydłem (spelunka Kruków)","spelunka-krukow",1820,1260,1],["Kancelaria Sędziego Vargi","kancelaria-vargi",1680,1260,1]];
for (const [name, f, w, h, g] of maps) {
  if (game.scenes.getName(name)) continue;
  await Scene.create({ name, width: w, height: h, padding: 0.05, background: { src: `systems/degenesis2/assets/maps/${f}.webp` },
    grid: { type: g, size: 70, distance: 1, units: "m", alpha: 0 } });
}
ui.notifications.info("Sceny przygody gotowe.");
